import { test, expect } from '@playwright/test';

test.describe('Unsaved Form Navigation Warning', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://example.com/form'); // Replace with the actual URL of the form
  });

  test('should show a warning when trying to navigate away with unsaved changes', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'John Doe'); // Assuming there's a label for the name field
    await page.fill(getByLabel('Email'), 'john.doe@example.com'); // Assuming there's a label for the email field

    const [dialog] = await Promise.all([
      page.waitForEvent('dialog'),
      page.click(getByText('Go to another page')) // Replace with the actual button or link to navigate away
    ]);

    expect(dialog.message()).toContain('You have unsaved changes.'); // Adjust the message as per the actual warning
    await dialog.dismiss();
  });

  test('should allow navigation if changes are saved', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'John Doe');
    await page.fill(getByLabel('Email'), 'john.doe@example.com');
    await page.click(getByText('Save')); // Assuming there's a save button

    await page.click(getByText('Go to another page')); // Replace with the actual button or link to navigate away
    expect(page.url()).toBe('http://example.com/another-page'); // Replace with the actual URL of the target page
  });
});
